        run: |
          flags="${{ matrix.rustflags }}"
          flags="${flags/-C target-feature=/}"
          flags="${flags//[- ]/}"
          echo "$flags"
          echo "flags=$flags" >> $GITHUB_ENV

      - name: Upload coverage to Codecov
