        uses: Wandalen/wretry.action@master
        with:
          action: codecov/codecov-action@v3
          attempt_limit: 6
          attempt_delay: 10000
          with: |
            files: ./lcov.txt
            flags: unittests
            verbose: true

  test-wasm:
