///             "serde",
///             "json"
///         ]
///     }
/// });
/// ```
///
/// Create a borrowed value of the form:
///
/// ```edition2018
/// # use simd_json::{json_typed, BorrowedValue};
/// #
/// let value: BorrowedValue = json_typed!(borrowed, {
